pub struct AuditEventDeleteMany<'repo, 'ctx> {
    repo: &'repo AuditEventRepository<'ctx>,
    hooks: Vec<std::sync::Arc<dyn roze_orm::OperationMiddleware<Self, u64, anyhow::Error> + 'repo>>,
    predicates: Vec<AuditEventPredicate>,
}

impl<'repo, 'ctx> AuditEventDeleteMany<'repo, 'ctx> {
    pub fn new(repo: &'repo AuditEventRepository<'ctx>) -> Self {
        Self {
            repo,
            hooks: Vec::new(),
            predicates: Vec::new(),
        }
    }

    pub fn where_(mut self, predicate: AuditEventPredicate) -> Self {
        self.predicates.push(predicate);
        self
    }

    pub fn where_all<I>(mut self, predicates: I) -> Self
    where
        I: IntoIterator<Item = AuditEventPredicate>,
    {
        self.predicates.extend(predicates);
        self
    }

    pub fn where_any<I>(mut self, predicates: I) -> Self
    where
        I: IntoIterator<Item = AuditEventPredicate>,
    {
        let predicates = predicates.into_iter().collect::<Vec<_>>();
        if !predicates.is_empty() {
            self.predicates.push(AuditEventPredicate::Or(predicates));
        }
        self
    }

    pub fn where_not(mut self, predicate: AuditEventPredicate) -> Self {
        self.predicates
            .push(AuditEventPredicate::Not(Box::new(predicate)));
        self
    }

    pub fn where_none<I>(mut self, predicates: I) -> Self
    where
        I: IntoIterator<Item = AuditEventPredicate>,
    {
        let predicates = predicates.into_iter().collect::<Vec<_>>();
        if !predicates.is_empty() {
            self.predicates
                .push(AuditEventPredicate::Not(Box::new(AuditEventPredicate::Or(
                    predicates,
                ))));
        }
        self
    }

    pub fn hook<H>(mut self, hook: H) -> Self
    where
        H: roze_orm::OperationMiddleware<Self, u64, anyhow::Error> + 'repo,
    {
        self.hooks.push(std::sync::Arc::new(hook));
        self
    }

    pub fn policy<I, D>(mut self, rules: I, deny_by_default: D) -> Self
    where
        I: IntoIterator<
            Item = std::sync::Arc<dyn roze_orm::Policy<Self, Error = anyhow::Error> + 'repo>,
        >,
        D: Fn() -> anyhow::Error + Send + Sync + 'repo,
    {
        self.hooks
            .push(std::sync::Arc::new(roze_orm::PolicyMiddleware::new(
                rules,
                deny_by_default,
            )));
        self
    }

    pub fn mixin<M>(self, mixin: M) -> Self
    where
        M: roze_orm::OperationMixin<Self>,
    {
        mixin.apply(self)
    }

    pub async fn exec(mut self) -> anyhow::Result<u64> {
        let hooks = std::mem::take(&mut self.hooks);
        roze_orm::execute_chain(&AuditEventDeleteManyTerminal, &hooks, self).await
    }

    async fn exec_unhooked(self) -> anyhow::Result<u64> {
        let mut query = self.repo.query();
        for predicate in &self.predicates {
            query = query.where_(predicate.clone());
        }
        let items = query.all().await?;
        let mut rows_affected = 0u64;
        for item in items {
            let result = self.repo.delete_one(item.id).exec().await?;
            rows_affected += result.rows_affected;
        }
        Ok(rows_affected)
    }
}

